(function(){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const gallery=()=>Array.isArray(window.AURORA_GALLERY)?window.AURORA_GALLERY:[];
 let activeFilter='all',lightboxIndex=0,context=null,observer=null;
 const heading=(en,cn,body='')=>`<div class="section-title"><p class="eyebrow">${en}</p><h2>${cn}</h2>${body?`<p class="section-desc">${body}</p>`:''}</div>`;
 function photoCard(p,index=0){return `<button class="photo-card" data-gallery-open="${esc(p.id)}" aria-label="放大查看：${esc(p.title)}"><div class="photo-frame"><img src="${esc(p.src)}" alt="${esc(p.title)}" loading="lazy" decoding="async" style="object-position:${esc(p.position||'center')}"><span class="photo-index">${String(index+1).padStart(2,'0')}</span><span class="photo-zoom" aria-hidden="true">↗</span></div><span class="photo-caption"><span><strong>${esc(p.title)}</strong><small>${esc(p.en)}</small></span><span class="photo-category">${{culture:'汽车文化',track:'出车记录',engineering:'技术细节'}[p.category]||'车队影像'}</span></span></button>`}
 function picks(){const items=gallery();const list=[items.find(p=>p.id==='culture-community-2025')||items.find(p=>p.category==='culture'),items.find(p=>p.category==='track'),items.find(p=>p.category==='engineering')].filter(Boolean);return list.length?list:items.slice(0,3)}
 function home(c){const imgs=picks();return `${window.AuroraCar.hero(c)}${window.AuroraStore.homeCategories(c.products)}<section class="container culture-preview page-section"><div class="section-heading">${heading('CULTURE IN MOTION','在场，才有共鸣。','从文化节的人群，到出车前的准备。热爱有它真实的样子。')}<a class="text-button arrow-link" href="#community">查看全部影像 ${c.icon('arrow')}</a></div><div class="home-photo-grid">${imgs.map(photoCard).join('')}</div></section>${window.AuroraStore.customBanner()}<section class="selection-section"><div class="container home-content"><section><div class="section-heading">${heading('CURATED PARTS','从整车，到每一个细节。')}<a class="text-button" href="#shop">查看全部配件 ${c.icon('arrow')}</a></div><div class="product-grid">${c.products.map(c.productCard).join('')}</div></section><aside class="side-stack"><section class="panel lab-teaser"><div class="eyebrow">PERFORMANCE LAB</div><h3>差异，看得见。</h3><p>从单项指标到多维画像，找到适合你的性能取向。</p><div class="teaser-bars" aria-label="模型计算对比示意"><span style="--bar:82%;--tone:#5b2377">Öhlins <i></i></span><span style="--bar:70%;--tone:#BA70CF">KW <i></i></span><span style="--bar:91%;--tone:#B98A2C">DSSV <i></i></span></div><div class="teaser-features"><span>柱状对比</span><span>五维雷达</span><span>多组曲线</span></div><a class="button primary" href="#lab">打开评测工作台 ${c.icon('arrow')}</a><small class="caption">模型计算 · 悬架性能趋势</small></section><a class="service-teaser" href="#service"><span class="service-teaser-icon">${c.icon('wrench')}</span><span><strong>把选择，变成合适的方案。</strong><small>FITMENT & INSTALLATION</small></span>${c.icon('arrow')}</a></aside></div></section>${c.journey()}<section class="container collaboration-band"><div><div class="eyebrow">BUILD SOMETHING TOGETHER</div><h2>一起，把性能说清楚。</h2><p>连接品牌、车主与专业服务，让每一次热爱都有回应。</p></div><button class="button ghost" data-action="partner">了解品牌合作 ${c.icon('arrow')}</button></section>`}
 function community(c){return `<div class="container culture-page"><header class="page-intro"><div><div class="eyebrow">CULTURE & COMMUNITY</div><h1>热爱，从来不只在赛道上。</h1><p>汽车文化节、真实出车与技术细节，一起构成极光的日常。</p></div><button class="button primary" data-action="event">记录体验意向 ${c.icon('arrow')}</button></header><section class="culture-feature"><div class="culture-feature-copy"><div class="eyebrow">PEOPLE. MACHINES. STORIES.</div><h2>因热爱而聚，<br>因体验而懂。</h2><p>从看见一辆车，到理解一个零件。<br>我们把现场的好奇，延续到每一次选型。</p><div class="culture-feature-links"><a class="text-button" href="#lab">去探索性能 ${c.icon('arrow')}</a><button class="text-button" data-action="partner">参与品牌合作 ${c.icon('arrow')}</button></div></div>${gallery().find(p=>p.category==='culture')?`<button class="culture-feature-photo" data-gallery-open="${esc(gallery().find(p=>p.category==='culture').id)}"><img src="${esc(gallery().find(p=>p.category==='culture').src)}" alt="${esc(gallery().find(p=>p.category==='culture').title)}"><span>汽车文化 · 现场记录 ${c.icon('arrow')}</span></button>`:''}</section><section class="gallery-section"><div class="section-heading">${heading('THE VISUAL JOURNAL','把现场留在这里。')}<div class="gallery-tabs" role="group" aria-label="筛选影像类别">${[['all','全部影像','ALL'],['culture','汽车文化','CULTURE'],['track','出车记录','ON TRACK'],['engineering','技术细节','ENGINEERING']].map(([id,cn,en])=>`<button data-gallery-filter="${id}" class="${activeFilter===id?'active':''}" aria-pressed="${activeFilter===id}"><b>${cn}</b><small>${en}</small></button>`).join('')}</div></div><div id="culture-gallery" class="culture-gallery">${gallery().filter(p=>activeFilter==='all'||p.category===activeFilter).map(photoCard).join('')}</div></section><section class="culture-guides"><div>${heading('GO DEEPER','从热爱，到更懂车。','把体验变成记录，把记录变成下一次选择的依据。')}</div><div class="article-list">${Object.entries(c.articles).map(([id,a])=>`<article class="article-card"><div class="article-label">${a.tag}</div><h3>${a.title}</h3><p>${id==='setup'?'建立一致的车型、工况与调校基线。':'检查车辆状态，准备测试记录，做好复盘。'}</p><button class="text-button" data-action="article" data-id="${id}">阅读完整指南 ${c.icon('arrow')}</button></article>`).join('')}</div></section></div>`}
 function openPhoto(id){const items=gallery();lightboxIndex=items.findIndex(p=>p.id===id);showPhoto()}
 function showPhoto(){const items=gallery(),p=items[lightboxIndex];if(!p||!context)return;context.modal(esc(p.title),`<div class="lightbox-media"><img src="${esc(p.src)}" alt="${esc(p.title)}"><button class="lightbox-arrow previous" data-gallery-step="-1" aria-label="上一张">←</button><button class="lightbox-arrow next" data-gallery-step="1" aria-label="下一张">→</button></div><div class="lightbox-description"><p>${esc(p.caption)}</p><span>${String(lightboxIndex+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span></div><p class="caption">${esc(p.en)} · 用户提供的项目影像</p>`);document.querySelector('#modal').classList.add('photo-dialog')}
 function reveal(){observer?.disconnect();const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)return;observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.photo-card,.collaboration-band,.culture-guides,.lab-teaser').forEach((el,i)=>{el.classList.add('will-reveal');el.style.setProperty('--reveal-delay',Math.min(i%3,2)*65+'ms');observer.observe(el)})}
 function mount(c){context=c;window.AuroraCar.mount(c);reveal();const app=document.querySelector("#app");app.classList.remove("route-enter");void app.offsetWidth;app.classList.add("route-enter")}
 document.addEventListener('click',e=>{const opener=e.target.closest('[data-gallery-open]');if(opener){openPhoto(opener.dataset.galleryOpen);return}const step=e.target.closest('[data-gallery-step]');if(step){lightboxIndex=(lightboxIndex+Number(step.dataset.galleryStep)+gallery().length)%gallery().length;showPhoto();return}const filter=e.target.closest('[data-gallery-filter]');if(filter){activeFilter=filter.dataset.galleryFilter;document.querySelectorAll('[data-gallery-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.galleryFilter===activeFilter);b.setAttribute('aria-pressed',String(b.dataset.galleryFilter===activeFilter))});document.querySelector('#culture-gallery').innerHTML=gallery().filter(p=>activeFilter==='all'||p.category===activeFilter).map(photoCard).join('');reveal()}});
 document.addEventListener('keydown',e=>{const d=document.querySelector('#modal');if(d?.open&&d.classList.contains('photo-dialog')&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();lightboxIndex=(lightboxIndex+(e.key==='ArrowRight'?1:-1)+gallery().length)%gallery().length;showPhoto()}});
 window.AuroraPages={home,community,mount,unmount(){observer?.disconnect();window.AuroraCar.unmount()}};
})();
